"""Balochi Sentiment Studio: transparent predictions and annotation review."""
import hashlib, io, json, unicodedata, re
from pathlib import Path
import pandas as pd
import streamlit as st
"""Dependency-free multinomial Naive Bayes. Python 3.11+."""
import csv, json, math, random, re, sys, unicodedata
from collections import Counter
from pathlib import Path
LABELS=['negative','neutral','positive']

def clean(text):
    text=''.join(unicodedata.normalize('NFKC',c) if '\ufb50'<=c<='\ufdff' or '\ufe70'<=c<='\ufeff' else c for c in text)
    return ' '.join(unicodedata.normalize('NFC',text).split())

def features(text,kind):
    # No stemming, translation, stopword removal or diacritic removal.
    words=[''.join(c if unicodedata.category(c)[0] in 'LM' else ' ' for c in clean(text))]
    words=words[0].split()
    if kind=='word': return Counter(words)
    # Within-word character trigrams; emojis cannot become shortcut features.
    return Counter(w[i:i+3] for word in words for w in ['^'+word+'$'] for i in range(max(0,len(w)-2)))

def fit(rows,kind,alpha):
    counts={c:Counter() for c in LABELS}; docs=Counter(); vocab=set()
    for r in rows:
        f=features(r['text'],kind); counts[r['label']].update(f); docs[r['label']]+=1; vocab.update(f)
    return {'kind':kind,'alpha':alpha,'counts':{c:dict(counts[c]) for c in LABELS},'docs':dict(docs),'vocab':sorted(vocab),'totals':{c:sum(counts[c].values()) for c in LABELS}}

def predict(model,text):
    vocab=set(model['vocab']); f=features(text,model['kind']); a=model['alpha']; n=sum(model['docs'].values())
    scores={c:math.log(model['docs'][c]/n)+sum(v*math.log((model['counts'][c].get(k,0)+a)/(model['totals'][c]+a*len(vocab))) for k,v in f.items() if k in vocab) for c in LABELS}
    return max(scores,key=scores.get)

def metrics(actual,pred):
    cm=[[sum(a==c and p==d for a,p in zip(actual,pred)) for d in LABELS] for c in LABELS]; per={}
    for i,c in enumerate(LABELS):
        tp=cm[i][i]; precision=tp/max(1,sum(row[i] for row in cm)); recall=tp/max(1,sum(cm[i])); f1=2*precision*recall/(precision+recall) if precision+recall else 0
        per[c]={'precision':precision,'recall':recall,'f1':f1,'support':sum(cm[i])}
    return {'accuracy':sum(a==p for a,p in zip(actual,pred))/len(actual),'macro_f1':sum(v['f1'] for v in per.values())/3,'per_class':per,'confusion_matrix':cm,'label_order':LABELS}

def run(root):
    with (root/'verified.csv').open(encoding='utf-8-sig',newline='') as f: rows=list(csv.DictReader(f))
    # Group compatibility-normalized exact matches before any split.
    groups={}
    for r in rows: groups.setdefault(unicodedata.normalize('NFKC',r['text']),[]).append(r)
    if any(len({r['label'] for r in group})>1 for group in groups.values()): raise ValueError('Conflicting labels')
    rows=[group[0] for group in groups.values()]
    train=[];val=[];test=[];rng=random.Random(42)
    for c in LABELS:
        subset=[r for r in rows if r['label']==c];rng.shuffle(subset); a=int(.6*len(subset)); b=int(.8*len(subset));train+=subset[:a];val+=subset[a:b];test+=subset[b:]
    assert not ({unicodedata.normalize('NFKC',r['text']) for r in train}&{unicodedata.normalize('NFKC',r['text']) for r in test+val})
    trials=[]
    for kind in ['word','char3']:
        for alpha in [.5,1.,2.]:
            m=fit(train,kind,alpha); score=metrics([r['label'] for r in val],[predict(m,r['text']) for r in val]);trials.append({'kind':kind,'alpha':alpha,'validation':score})
    best=max(trials,key=lambda t:t['validation']['macro_f1']); model=fit(train+val,best['kind'],best['alpha']); pred=[predict(model,r['text']) for r in test]
    majority=Counter(r['label'] for r in train+val).most_common(1)[0][0]
    result={'method':'Multinomial Naive Bayes','seed':42,'sizes':{'train':len(train),'validation':len(val),'test':len(test)},'compatibility_duplicates_removed':len(groups) and sum(len(g)-1 for g in groups.values()),'trials':trials,'selected':{'kind':best['kind'],'alpha':best['alpha']},'test':metrics([r['label'] for r in test],pred),'majority_test':metrics([r['label'] for r in test],[majority]*len(test))}
    out=root/'results';out.mkdir(exist_ok=True)
    (out/'baseline_metrics.json').write_text(json.dumps(result,indent=2),encoding='utf-8');(out/'baseline_model.json').write_text(json.dumps(model,ensure_ascii=False),encoding='utf-8')
    for name,items in [('split.csv',[dict(r,split=s) for s,rs in [('train',train),('validation',val),('test',test)] for r in rs]),('predictions.csv',[dict(r,predicted=p) for r,p in zip(test,pred)])]:
        with (out/name).open('w',encoding='utf-8-sig',newline='') as f:
            w=csv.DictWriter(f,fieldnames=list(items[0]));w.writeheader();w.writerows(items)
    print(json.dumps({k:v for k,v in result.items() if k!='trials'},indent=2))


MODEL_BUNDLE = ''
ROOT = Path(__file__).resolve().parent
st.set_page_config(page_title='Balochi · Sentiment Studio', page_icon='◈', layout='wide')
@st.cache_resource
def load_assets():
    import base64, zlib
    assets=json.loads(zlib.decompress(base64.b64decode(MODEL_BUNDLE)))
    return json.loads(assets['baseline_model.json']),json.loads(assets['baseline_metrics.json'])

def assess(text, model):
    value = clean(text)
    if not value: return None, 'Enter a sentence to begin.'
    if not any(c.isalpha() and 'ARABIC' in unicodedata.name(c,'') for c in value): return None, 'Use Balochi in Perso-Arabic script.'
    if not (set(features(value,model['kind'])) & set(model['vocab'])): return None, 'No learned patterns found. Try a complete sentence.'
    return predict(model,value), None
def split_sentences(text):
    # Preserve punctuation; split Arabic/Latin sentence endings and newlines.
    return [part.strip() for part in re.findall(r'[^۔!?؟.\n]+(?:[۔!?؟.]+|(?=\n)|$)', text) if part.strip()]

